commands.command:
"<USER>\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command '$original = Get-Content -LiteralPath input.json -Raw | ConvertFrom-Json
$export = Get-Content -LiteralPath output.json -Raw | ConvertFrom-Json
$expectedTotal = ($original.values | Measure-Object -Sum).Sum
$expectedHash = (Get-FileHash -LiteralPath input.json -Algorithm SHA256).Hash.ToLowerInvariant()
if ($export.generation -cne $original.generation) { throw '"'Generation mismatch' }
if ("'$export.total -ne $expectedTotal) { throw '"'Total mismatch' }
if ("'$export.input_sha256 -cne $expectedHash) { throw '"'SHA256 mismatch' }
if (("'$export.PSObject.Properties.Name | Sort-Object) -join '"',' -cne 'generation,input_sha256,total') { throw 'Unexpected fields' }
Get-Content -LiteralPath output.json
Write-Output 'Independent validation passed.'"
